using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text.Json;
using XybridBolt;

class NativeWorker {
 static XybridEnvelope Text(string value,string role)=>new XybridEnvelope(new XybridEnvelopeKind.Text(value),new[]{new XybridMetadataEntry("xybrid.role",role)});
 static void Main(string[] args) {
  var native=Environment.GetEnvironmentVariable("NPC_NATIVE_LIB")??throw new InvalidOperationException("NPC_NATIVE_LIB must name the installed demo native library");
  NativeLibrary.SetDllImportResolver(typeof(XybridModel).Assembly,(name,assembly,path)=>name=="xybrid_bolt"?NativeLibrary.Load(native):IntPtr.Zero);
  using var model=XybridModel.FromDirectory(args[0]);
  XybridConversationContext context=null;string persona=null;string input;
  try {
   while((input=Console.ReadLine())!=null) {
    using var doc=JsonDocument.Parse(input);var request=doc.RootElement;
    string system=request.GetProperty("persona").GetString();
    if(system!=persona) {context?.Dispose();context=new XybridConversationContext();context.SetSystem(Text(system,"system"));persona=system;}
    string prompt=request.GetProperty("prompt").GetString();
    string grammar=request.TryGetProperty("grammar",out var grammarValue)&&grammarValue.ValueKind==JsonValueKind.String?grammarValue.GetString():null;
    uint max=request.TryGetProperty("max_tokens",out var maxValue)?maxValue.GetUInt32():112u;
    var config=new XybridGenerationConfig(max,1f,.95f,0f,64u,1f,new[]{"<turn|>","<|turn>"},grammar,Array.Empty<XybridToolDefinition>());
    var events=new List<object>();var clock=Stopwatch.StartNew();double? first=null;ulong stream=0;
    try {
     stream=model.RunStreamWithContext(Text(prompt,"user"),context,new XybridRunOptions(config,Array.Empty<XybridAbortSignal>(),false,0,null));
     while(true) {
      var evt=model.StreamNext(stream);if(evt.Kind==XybridStreamEventKind.Complete)break;
      if(evt.Kind==XybridStreamEventKind.Token && evt.Token is {} token && !string.IsNullOrEmpty(token.Token)) {
       double elapsed=clock.Elapsed.TotalSeconds;first??=elapsed;events.Add(new{seconds=elapsed,text=token.Token});
      }
     }
     var result=model.StreamResult(stream);double total=clock.Elapsed.TotalSeconds;
     if(result.ExecutionTarget!=XybridExecutionTarget.Local)throw new InvalidOperationException("Expected local execution");
     string raw=result.Envelope.Kind is XybridEnvelopeKind.Text text?text.Value:"";
     var metadata=result.Envelope.Metadata.GroupBy(item=>item.Key).ToDictionary(group=>group.Key,group=>group.Last().Value);
     metadata["execution_target"]="local";
     if(result.Metrics.DecodeTps is {} decode)metadata["decode_tps"]=decode.ToString(System.Globalization.CultureInfo.InvariantCulture);
     if(result.Metrics.TokensOut is {} count)metadata["tokens_generated"]=count.ToString(System.Globalization.CultureInfo.InvariantCulture);
     Console.WriteLine(JsonSerializer.Serialize(new{raw,seconds=total,ttft_seconds=first,events,metadata,worker_peak_rss_kib=Process.GetCurrentProcess().PeakWorkingSet64/1024}));
    }catch(Exception error) {Console.WriteLine(JsonSerializer.Serialize(new{error=error.ToString(),seconds=clock.Elapsed.TotalSeconds,events}));}
    finally {if(stream!=0)model.StreamClose(stream);}
   }
  }finally {context?.Dispose();}
 }
}

