def digest(path):
 h=hashlib.sha256()
 with path.open('rb') as file:
  for chunk in iter(lambda:file.read(8*1024*1024),b''):h.update(chunk)
 return h.hexdigest()
active=None;stop=threading.Event()
def monitor():
 with (root/'host.jsonl').open('w') as log:
  while not stop.is_set():
   row={'timestamp':time.time(),'stage':state['status'],'vm_stat':subprocess.check_output(['vm_stat'],text=True),'swap':subprocess.check_output(['sysctl','vm.swapusage'],text=True).strip()}
   if active is not None:row['process']=subprocess.run(['ps','-p',str(active.pid),'-o','pid,rss,%cpu,etime'],capture_output=True,text=True).stdout
   log.write(json.dumps(row)+'\n');log.flush();stop.wait(2)
try:
 save()
 env=os.environ.copy();env['NPC_NATIVE_LIB']=str(native)
 source=[('Gemma4NPC-E2B-Q4_K_M',demo/'Assets/StreamingAssets/XybridModels/gemma4npc-e2b-q4','2a6f2d10f8ca60f357048a8ec9dd52c7d2f9f81d777ccd8c1a86373a89295846'),('Gemma3NPC-Q4_K_M',demo/'.context/voice-survey/gemma3npc','8d1d1a7f693237fcc6515274d2a6665fe867471a1d95005a39e21ec1a3c8c384')]
 models={};provenance=[]
 for label,directory,expected in source:
  meta=json.loads((directory/'model_metadata.json').read_text())
  target=root/'models'/label;target.mkdir(parents=True,exist_ok=True)
  assert meta['execution_template']['context_length']==8192
  for name in meta['files']:
   original=directory/name;sha=digest(original)
   if sha!=expected:raise RuntimeError('Unexpected model checksum '+label)
   link=target/name
   if not link.exists():link.symlink_to(original)
   provenance.append({'model':label,'file':name,'sha256':sha,'bytes':original.stat().st_size})
  (target/'model_metadata.json').write_text(json.dumps(meta,indent=2));models[label]=target
 code=fixture/'Assets/XybridAvatarDemo/Runtime/GatekeeperNpcModel.cs'
 manifest={'sdk':'installed Unity native 0.9.0 with pinned 0.9.0 generated bindings','dotnet':subprocess.check_output(['/opt/homebrew/bin/dotnet','--version'],text=True).strip(),'hardware':subprocess.check_output(['sysctl','-n','machdep.cpu.brand_string'],text=True).strip(),'memoryBytes':subprocess.check_output(['sysctl','-n','hw.memsize'],text=True).strip(),'contextLength':8192,'native_sha256':digest(native),'promptSource_sha256':digest(code),'promptSourceCommit':'91948f7','models':provenance,'conditions':'Headless; no voice model loaded by harness; automatic native offload and helper threads; primes exclude disk-cold loading; hashes read before inference.'}
 (root/'environment.json').write_text(json.dumps(manifest,indent=2))
 # Point the fixture-only verifier at the runtime installed on this Mac.
 verify=fixture/'tools/npc-quality/verify.py';verify.write_text(verify.read_text().replace('net8.0','net10.0'))
 subprocess.run(['/opt/homebrew/bin/python3',str(verify),'--dotnet','/opt/homebrew/bin/dotnet'],check=True,env=env)
 thread=threading.Thread(target=monitor);thread.start()
 jobs=[(source[0][0],1,True),(source[1][0],1,True),(source[1][0],2,False),(source[0][0],2,False)]
 for label,run,sequence in jobs:
  state['status']=label+'-pass-'+str(run);save()
  receipt=out/(label+'-pass-'+str(run)+'.jsonl')
  command=['/opt/homebrew/bin/python3',str(fixture/'tools/npc-quality/run.py'),'--model',str(models[label]),'--label',label,'--worker',str(root/'native-worker'),'--dotnet','/opt/homebrew/bin/dotnet','--exporter',str(fixture/'tools/npc-quality/bin/Debug/net10.0/ScenarioChecks.dll'),'--output',str(receipt),'--repeats','1']
  if sequence:command.append('--sequence')
  with (out/(label+'-pass-'+str(run)+'.log')).open('w') as log:
   active=subprocess.Popen(command,stdout=log,stderr=log,env=env,start_new_session=True)
   try:exit_code=active.wait(timeout=600)
   except subprocess.TimeoutExpired:
    import signal
    os.killpg(active.pid,signal.SIGTERM);active.wait(timeout=20);raise
  if exit_code:raise RuntimeError('Runner failed '+label+'; see '+str(receipt)+'.log')
  rows=[json.loads(line) for line in receipt.read_text().splitlines()]
  requests=[row for row in rows if row.get('kind')!='state']
  if any(row.get('error') for row in requests):raise RuntimeError('Native inference failed; inspect receipts')
  if any(row.get('metadata',{}).get('execution_target')!='local' for row in requests):raise RuntimeError('Missing local execution receipt')
  state['completed'].append(str(receipt));save()
 state['status']='complete';save()
except Exception as error:
 state['status']='failed';state['error']=repr(error);save();raise
finally:
 stop.set()
 if 'thread' in globals():thread.join(timeout=5)

